window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-83fe2a54c3432386"]={"versions": [{"id": "FIG-83fe2a54c3432386", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Timing-Events für VFB-Kommunikation im Kontext der AUTOSAR Timing Extensions (TPS Adaptive Platform Timing Extensions). Das Diagramm definiert Metamodell-Elemente zur Erfassung von Zeitpunkten beim Senden und Empfangen von Datenprototypen an Port-Schnittstellen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>TDEventVfbPort</strong> (kursiv/abstrakt): Spezialisierung von <code>TDEventVfb</code> bzw. <code>TimingDescriptionEvent</code>. Enthält das Attribut <code>+ isExternal: Boolean</code> und referenziert über die gerichtete Assoziation <code>+port</code> optional (<code>0..1</code>) ein <code>PortPrototype</code> (mit den Stereotypen/Superklassen <code>AtpBlueprintable</code>, <code>AtpPrototype</code>).\n</li><li><strong>TDEventVariableDataPrototype</strong>: Konkrete Spezialisierung von <code>TDEventVfbPort</code>. Besitzt das obligatorische Attribut <code>+ tdEventVariableDataPrototypeType: TDEventVariableDataPrototypeTypeEnum</code> und referenziert über die gerichtete Assoziation <code>+dataElement</code> genau ein (<code>1</code>) <code>VariableDataPrototype</code> (Superklasse <code>AutosarDataPrototype</code>).\n</li><li><strong>TDEventVariableDataPrototypeTypeEnum</strong> (<code>«enumeration»</code>): Enumeration zur Differenzierung der Ereignisart mit den Literalen:\n<ul class=\"fig-list\"><li><code>variableDataPrototypeSent</code>\n</li><li><code>variableDataPrototypeReceived</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne direkte Verhaltenssequenz. Die Ereignisse repräsentieren Laufzeit-Beobachtungspunkte auf VFB-Ebene: Das Auftreten eines <code>TDEventVariableDataPrototype</code> wird ausgelöst, sobald ein Datenelement (<code>VariableDataPrototype</code>) an einem Port gesendet (<code>variableDataPrototypeSent</code>) oder empfangen (<code>variableDataPrototypeReceived</code>) wird. Die Eigenschaft <code>isExternal</code> kennzeichnet, ob das Ereignis an einer systemexternen Schnittstelle beobachtet wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Metamodell erzwingt für jede Instanz von <code>TDEventVariableDataPrototype</code> die Festlegung des Ereignistyps (<code>TDEventVariableDataPrototypeTypeEnum</code>) sowie die Angabe genau eines Datenelements (<code>+dataElement 1</code>). Die Port-Referenz (<code>+port</code>) ist mit Kardinalität <code>0..1</code> optional. Werkzeuge für Timing-Analysen müssen das Attribut <code>isExternal</code> von <code>TDEventVfbPort</code> auswerten.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-b67161c5b0a5bae3", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Timing-Events für VFB-Kommunikation im Kontext der AUTOSAR Timing Extensions (TPS Adaptive Platform Timing Extensions). Das Diagramm definiert Metamodell-Elemente zur Erfassung von Zeitpunkten beim Senden und Empfangen von Datenprototypen an Port-Schnittstellen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>TDEventVfbPort</strong> (kursiv/abstrakt): Spezialisierung von <code>TDEventVfb</code> bzw. <code>TimingDescriptionEvent</code> ohne eigene Attribute. Referenziert über die gerichtete Assoziation <code>+port</code> optional (<code>0..1</code>) ein <code>PortPrototype</code> (mit den Stereotypen/Superklassen <code>AtpBlueprintable</code>, <code>AtpPrototype</code>).\n</li><li><strong>TDEventVariableDataPrototype</strong>: Konkrete Spezialisierung von <code>TDEventVfbPort</code>. Besitzt das optionale Attribut <code>+ tdEventVariableDataPrototypeType: TDEventVariableDataPrototypeTypeEnum [0..1]</code> und referenziert über die gerichtete Assoziation <code>+dataElement</code> optional (<code>0..1</code>) ein <code>VariableDataPrototype</code> (Superklasse <code>AutosarDataPrototype</code>).\n</li><li><strong>TDEventVariableDataPrototypeTypeEnum</strong> (<code>«enumeration»</code>): Enumeration zur Differenzierung der Ereignisart mit den Literalen:\n<ul class=\"fig-list\"><li><code>variableDataPrototypeSent</code>\n</li><li><code>variableDataPrototypeReceived</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne direkte Verhaltenssequenz. Die Ereignisse repräsentieren Laufzeit-Beobachtungspunkte auf VFB-Ebene: Das Auftreten eines <code>TDEventVariableDataPrototype</code> markiert das Senden (<code>variableDataPrototypeSent</code>) oder Empfangen (<code>variableDataPrototypeReceived</code>) eines Datenelements an einem Port. Werden Typ oder Datenelement nicht spezifiziert, dient das Ereignis als allgemeinerer Timing-Beobachtungspunkt auf Port-Ebene.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Sowohl das Attribut <code>tdEventVariableDataPrototypeType</code> als auch die Referenz <code>+dataElement</code> sind optional mit Kardinalität <code>0..1</code>. Das vormalige Attribut <code>isExternal</code> an <code>TDEventVfbPort</code> existiert nicht mehr im Diagramm. Analysewerkzeuge müssen Modelle verarbeiten können, bei denen Datenelement oder Ereignistyp nicht explizit gebunden sind.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-83fe2a54c3432386", "to": "FIG-b67161c5b0a5bae3", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Attribut <code>+ isExternal: Boolean</code> in Klasse <code>TDEventVfbPort</code> entfernt.\n</li><li>Attribut <code>+ tdEventVariableDataPrototypeType: TDEventVariableDataPrototypeTypeEnum</code> in <code>TDEventVariableDataPrototype</code>: Multiplizität von implizit <code>1</code> auf optional <code>[0..1]</code> geändert.\n</li><li>Assoziation <code>+dataElement</code> von <code>TDEventVariableDataPrototype</code> zu <code>VariableDataPrototype</code>: Kardinalität von <code>1</code> auf <code>0..1</code> geändert.\n</li></ul>"}]};
